async def act(page):
    import urllib.parse

    # Target post title substring and the exact comment text to post
    target_substring = "How to get rid of unwanted Christmas presents"
    comment_text = "Interesting perspective."

    # 1) Primary discovery attempt: use the site-search helper to find the post by title.
    # Utility: create_curated_collection_by_search uses the visible search widget (role="complementary")
    # and returns a list of post dicts {title, url}. It navigates to '/' as part of its contract.
    try:
        matches = await create_curated_collection_by_search(page, target_substring, max_results=50)
    except Exception:
        matches = []

    # 2) Fallback discovery: scan homepage headings for the broader keyword 'Christmas'.
    # Utility: monitor_keyword_and_notify scans article headings on the homepage and returns matched title/url pairs.
    if not matches:
        try:
            matches = await monitor_keyword_and_notify(page, "Christmas", check_interval_minutes=60, notify_via="email", max_results=50)
        except Exception:
            matches = []

    # 3) If no discovery results, stop (no reliable UI path from current state)
    if not matches or not isinstance(matches, list):
        return

    # 4) Pick the best candidate: prefer a title containing the target substring (case-insensitive), else first result
    chosen = None
    for m in matches:
        if not isinstance(m, dict):
            continue
        title = (m.get("title") or "").strip()
        if title and target_substring.lower() in title.lower():
            chosen = m
            break
    if chosen is None and len(matches) > 0 and isinstance(matches[0], dict):
        chosen = matches[0]

    if not chosen or not isinstance(chosen, dict):
        return

    raw_href = chosen.get("url")
    if not raw_href:
        return

    # 5) Navigate to the chosen post URL (resolve relative URLs)
    try:
        if raw_href.startswith("http://") or raw_href.startswith("https://"):
            await page.goto(raw_href)
        else:
            await page.goto(urllib.parse.urljoin(page.url, raw_href))
    except Exception:
        return

    # 6) Defensive wait for main region to appear (if present)
    try:
        main = page.get_by_role("main")
        if await main.count() > 0:
            await main.nth(0).wait_for(timeout=5000)
    except Exception:
        pass

    # 7) Try to scope to the article that contains the post link/title (prefer article-scoped interactions)
    article_locator = None
    try:
        link_locator = page.get_by_role("link", name=target_substring)
        if await link_locator.count() > 0:
            articles = page.get_by_role("article")
            if await articles.count() > 0:
                filtered = articles.filter(has=link_locator)
                if await filtered.count() > 0:
                    article_locator = filtered.nth(0)
        if article_locator is None:
            articles_all = page.get_by_role("article")
            if await articles_all.count() > 0:
                article_locator = articles_all.nth(0)
    except Exception:
        article_locator = None

    # 8) Locate a comment textbox, preferring one scoped to the article
    comment_locator = None
    search_roots = [article_locator] if article_locator is not None else []
    search_roots.append(page)

    for root in search_roots:
        if root is None:
            continue
        try:
            tb_named = root.get_by_role("textbox", name="Comment")
            if await tb_named.count() > 0:
                comment_locator = tb_named.nth(0)
                break
        except Exception:
            pass
        try:
            tbs = root.get_by_role("textbox")
            cnt = await tbs.count()
            if cnt == 1:
                comment_locator = tbs.nth(0)
                break
            elif cnt > 1:
                selected = None
                for i in range(cnt):
                    candidate = tbs.nth(i)
                    name = ""
                    try:
                        name = (await candidate.get_attribute('aria-label')) or ""
                    except Exception:
                        name = ""
                    try:
                        placeholder = (await candidate.get_attribute('placeholder')) or ""
                    except Exception:
                        placeholder = ""
                    combined = (name + " " + placeholder).lower()
                    if 'comment' in combined or 'reply' in combined:
                        selected = candidate
                        break
                if selected is not None:
                    comment_locator = selected
                    break
                # last-resort: pick the last textbox (comment often last)
                comment_locator = tbs.nth(cnt - 1)
                break
        except Exception:
            pass

    if comment_locator is None:
        # No comment box found; stop to avoid brittle interactions
        return

    # 9) Fill the comment text exactly as requested
    try:
        await comment_locator.fill(comment_text)
    except Exception:
        try:
            await comment_locator.click()
            await comment_locator.type(comment_text)
        except Exception:
            return

    # 10) Best-effort: fill common name/email fields scoped to article/page to aid submission
    root_for_meta = article_locator if article_locator is not None else page
    name_candidates = ["Name", "Your name", "Author", "Full name"]
    for nm in name_candidates:
        try:
            loc = root_for_meta.get_by_role("textbox", name=nm)
            if await loc.count() > 0:
                try:
                    await loc.nth(0).fill("Commenter")
                except Exception:
                    pass
                break
        except Exception:
            continue

    email_candidates = ["Email", "Your email", "E-mail", "E-mail (will not be published)"]
    for em in email_candidates:
        try:
            loc = root_for_meta.get_by_role("textbox", name=em)
            if await loc.count() > 0:
                try:
                    await loc.nth(0).fill("commenter@example.com")
                except Exception:
                    pass
                break
        except Exception:
            continue

    # 11) Attempt to submit: prefer clicking a button scoped to the article
    submitted = False
    try:
        buttons_root = article_locator if article_locator is not None else page
        btns = buttons_root.get_by_role("button")
        btn_count = await btns.count()
        for i in range(btn_count):
            btn = btns.nth(i)
            label = ""
            try:
                label = (await btn.inner_text() or "").strip().lower()
            except Exception:
                try:
                    label = (await btn.get_attribute('aria-label') or "").strip().lower()
                except Exception:
                    label = ""
            if any(tok in label for tok in ["post", "submit", "comment", "send", "reply"]):
                try:
                    await btn.click()
                    submitted = True
                    break
                except Exception:
                    continue
    except Exception:
        submitted = False

    # 12) Keyboard fallback: try Control+Enter, then Enter in the comment box
    if not submitted:
        try:
            await comment_locator.press('Control+Enter')
            submitted = True
        except Exception:
            try:
                await comment_locator.press('Enter')
                submitted = True
            except Exception:
                submitted = False

    return

